import React, { Component, Fragment } from "react";
import { connect } from "react-redux";
import PropTypes from "prop-types";
import AppNavbar from "./components/AppNavbar";
import ShoppingList from "./ShoppingList";
import ItemModal from "./ItemModal";

class Pages extends Component {
  render() {
    const ProcessGroups = (
      <Fragment>
        <ItemModal />
        <ShoppingList />
      </Fragment>
    );
    const Items = <Fragment>items</Fragment>;
    return (
      <div>
        {this.props.page.page === "ProcessGroups" ? ProcessGroups : Items}
      </div>
    );
  }
}

Pages.propTypes = {
  page: PropTypes.object.isRequired
};

const mapStateToProps = state => ({
  page: state.page //posts is from the root reducer. Items is from the postReducer, which is ultimately getting the action from the postAction.  This expression then allows for use of this.props.posts
});

export default connect(mapStateToProps, null)(Pages);
